"use client"

import { Menu } from "@base-ui/react/menu"
import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"
import { ArrowDown01Icon, Menu01Icon } from "@hugeicons/core-free-icons"
import {
  Drawer,
  DrawerContent,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/registry/platformscode/ui/drawer"
import { cn } from "@/lib/utils"
import type { ReactNode } from "react"

export type NavMenuEntry = {
  label: ReactNode
  href?: string
  onClick?: () => void

  icon?: IconSvgElement

  helper?: ReactNode

  badge?: ReactNode
}

export type NavItem = {
  label: ReactNode
  href?: string
  onClick?: () => void

  selected?: boolean
  disabled?: boolean

  menu?: NavMenuEntry[]
}

function navItemClass(selected?: boolean, disabled?: boolean) {
  return cn(
    "relative inline-flex h-full items-center gap-1 rounded-[2px] border-0 bg-transparent px-4 text-base font-medium no-underline transition-colors lg:px-6",
    "focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/40",
    "after:absolute after:inset-x-2 after:bottom-0 after:h-2 after:rounded-full after:transition-opacity",
    disabled
      ? "cursor-not-allowed text-muted-foreground after:hidden"
      : selected
        ? cn(
            "cursor-pointer bg-primary font-semibold text-primary-foreground hover:bg-primary-hover active:bg-primary-hover",
            "after:bg-primary-bright after:opacity-100"
          )
        : cn(
            "cursor-pointer text-foreground hover:bg-muted active:bg-border",
            "after:bg-input after:opacity-0 hover:after:opacity-100 data-[popup-open]:after:opacity-100",
            "active:after:bg-foreground active:after:opacity-100"
          )
  )
}

function EntryContent({ entry }: { entry: NavMenuEntry }) {
  return (
    <>
      {entry.icon && (
        <span
          className="flex shrink-0 items-center justify-center rounded-md bg-primary-light p-3 text-primary"
          aria-hidden
        >
          <HugeiconsIcon icon={entry.icon} className="size-5" />
        </span>
      )}
      <span className="flex min-w-0 grow flex-col gap-0.5">
        <span className="entry-label text-base font-semibold text-foreground">
          {entry.label}
        </span>
        {entry.helper && (
          <span className="text-sm leading-5 text-muted-foreground">
            {entry.helper}
          </span>
        )}
      </span>
      {entry.badge && <span className="ms-auto shrink-0">{entry.badge}</span>}
    </>
  )
}

const ENTRY_CLASS =
  "flex w-full min-w-[300px] cursor-pointer items-center gap-4 rounded-md border-0 bg-transparent px-4 py-2 text-start no-underline outline-none data-[highlighted]:bg-muted data-[highlighted]:[&_.entry-label]:underline active:bg-border"

function DesktopItem({ item }: { item: NavItem }) {
  if (item.menu?.length) {
    return (
      <Menu.Root>
        <Menu.Trigger
          className={navItemClass(item.selected, item.disabled)}
          disabled={item.disabled}
        >
          {item.label}
          <HugeiconsIcon icon={ArrowDown01Icon} className="size-4 shrink-0" aria-hidden />
        </Menu.Trigger>
        <Menu.Portal>
          <Menu.Positioner sideOffset={8} align="start">
            <Menu.Popup className="z-50 rounded-md border border-border bg-card p-2 shadow-lg outline-none">
              {item.menu.map((entry, i) =>
                entry.href ? (
                  <Menu.LinkItem key={i} href={entry.href} className={ENTRY_CLASS}>
                    <EntryContent entry={entry} />
                  </Menu.LinkItem>
                ) : (
                  <Menu.Item key={i} onClick={entry.onClick} className={ENTRY_CLASS}>
                    <EntryContent entry={entry} />
                  </Menu.Item>
                )
              )}
            </Menu.Popup>
          </Menu.Positioner>
        </Menu.Portal>
      </Menu.Root>
    )
  }

  const className = navItemClass(item.selected, item.disabled)
  if (item.href && !item.disabled) {
    return (
      <a
        href={item.href}
        aria-current={item.selected ? "page" : undefined}
        className={className}
      >
        {item.label}
      </a>
    )
  }
  return (
    <button
      type="button"
      onClick={item.onClick}
      disabled={item.disabled}
      aria-current={item.selected ? "page" : undefined}
      className={className}
    >
      {item.label}
    </button>
  )
}

function DrawerItem({ item }: { item: NavItem }) {
  const rowClass = cn(
    "flex w-full items-center gap-3 rounded-sm px-4 py-3 text-start text-sm font-semibold no-underline",
    item.disabled
      ? "cursor-not-allowed text-muted-foreground"
      : item.selected
        ? "bg-primary-light text-primary"
        : "text-foreground active:bg-muted"
  )

  if (item.menu?.length) {
    return (
      <div className="flex flex-col">
        <span className={cn(rowClass, "text-muted-foreground")}>{item.label}</span>
        {item.menu.map((entry, i) => {
          const content = <EntryContent entry={entry} />
          return entry.href ? (
            <a key={i} href={entry.href} className={cn(ENTRY_CLASS, "ps-8")}>
              {content}
            </a>
          ) : (
            <button
              key={i}
              type="button"
              onClick={entry.onClick}
              className={cn(ENTRY_CLASS, "ps-8")}
            >
              {content}
            </button>
          )
        })}
      </div>
    )
  }

  if (item.href && !item.disabled) {
    return (
      <a
        href={item.href}
        aria-current={item.selected ? "page" : undefined}
        className={rowClass}
      >
        {item.label}
      </a>
    )
  }
  return (
    <button
      type="button"
      onClick={item.onClick}
      disabled={item.disabled}
      aria-current={item.selected ? "page" : undefined}
      className={rowClass}
    >
      {item.label}
    </button>
  )
}

/**
 * Brand slot for the header: logo mark, divider and a two-line title.
 * Renders an `<a>` element when `href` is set, otherwise a `<span>`.
 */
export function NavigationHeaderBrand({
  mark,
  title,
  subtitle,
  href,
}: {
  /** Logo mark element (image or monogram). */
  mark: ReactNode
  /** Entity name, bold line. */
  title: ReactNode
  /** Muted second line (e.g. the domain). */
  subtitle?: ReactNode
  /** Makes the brand a link to this URL. */
  href?: string
}) {
  const content = (
    <span className="flex min-w-0 items-center">
      {mark}
      {(title || subtitle) && (
        <span
          className="mx-2 h-12 w-px shrink-0 bg-black/20 sm:mx-4"
          aria-hidden
        />
      )}
      <span className="flex min-w-0 flex-col">
        <span className="truncate text-sm font-bold text-foreground">
          {title}
        </span>
        {subtitle && (
          <span
            className="truncate font-mono text-xs text-muted-foreground"
            dir="ltr"
          >
            {subtitle}
          </span>
        )}
      </span>
    </span>
  )
  return href ? (
    <a href={href} className="min-w-0 no-underline">
      {content}
    </a>
  ) : (
    content
  )
}

/**
 * DGA top navigation bar: brand, nav items with dropdown menus and the
 * official hover pill, primary actions and a skip link. The mobile variant
 * moves the items into a bottom drawer. Renders a `<header>` element.
 *
 * Documentation: [كود المنصات](https://x7md-lab.github.io/platformscode-registry/)
 */
export function NavigationHeader({
  logo,
  items,
  actions,
  mobile = false,
  sticky = false,
  skipHref = "#main",
  skipLabel = "تخطي إلى المحتوى",
  navLabel = "التنقل الرئيسي",
  drawerTitle = "القائمة",
  className,
}: {
  /** Brand slot, usually a `NavigationHeaderBrand`. */
  logo: ReactNode
  /** Navigation items; entries with `menu` open a dropdown. */
  items: NavItem[]
  /** End-side actions (e.g. a login button). */
  actions?: ReactNode
  /** Switches to the hamburger + bottom drawer variant. */
  mobile?: boolean
  /** Sticks the bar to the top of the viewport. */
  sticky?: boolean
  /** Target of the skip-to-content link. */
  skipHref?: string
  /** Label of the skip-to-content link. */
  skipLabel?: ReactNode
  /** Accessible name of the navigation landmark. */
  navLabel?: string
  /** Title shown at the top of the mobile drawer. */
  drawerTitle?: ReactNode
  className?: string
}) {
  const skipLink = (
    <a
      href={skipHref}
      className="sr-only rounded-sm bg-primary text-sm font-semibold text-primary-foreground focus:not-sr-only focus:absolute focus:start-2 focus:top-2 focus:z-50 focus:px-3 focus:py-2"
    >
      {skipLabel}
    </a>
  )

  const barClass = cn(
    "relative z-40 h-[72px] w-full bg-card after:absolute after:inset-x-0 after:bottom-0 after:block after:h-px after:w-full after:bg-border",
    sticky && "sticky top-0",
    className
  )

  if (mobile) {
    return (
      <header role="banner" className={barClass}>
        {skipLink}
        <div className="relative mx-auto flex h-full w-full max-w-3xl items-center gap-3 px-5">
        <Drawer showSwipeHandle>
          <DrawerTrigger
            aria-label={navLabel}
            className="flex size-9 cursor-pointer items-center justify-center rounded-sm border-0 bg-transparent text-foreground active:bg-muted focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/40"
          >
            <HugeiconsIcon icon={Menu01Icon} className="size-5" aria-hidden />
          </DrawerTrigger>
          <DrawerContent>
            <DrawerHeader className="pb-2">
              <DrawerTitle>{drawerTitle}</DrawerTitle>
            </DrawerHeader>
            <nav
              aria-label={navLabel}
              className="flex min-h-0 flex-1 flex-col gap-1 overflow-y-auto p-4 pt-2"
            >
              {items.map((item, i) => (
                <DrawerItem key={i} item={item} />
              ))}
            </nav>
            {actions && (
              <div className="flex shrink-0 flex-col gap-2 border-t border-border p-4 pb-[max(1rem,env(safe-area-inset-bottom))]">
                {actions}
              </div>
            )}
          </DrawerContent>
        </Drawer>
          {}
          <div className="flex min-w-0 items-center">{logo}</div>
        </div>
      </header>
    )
  }

  return (
    <header role="banner" className={barClass}>
      {skipLink}
      <nav
        aria-label={navLabel}
        className="mx-auto flex h-full w-full max-w-3xl items-center justify-between gap-4 px-5 lg:max-w-5xl"
      >
        <div className="flex shrink-0 items-center">{logo}</div>
        <ul className="m-0 flex h-full grow list-none items-center p-0">
          {items.map((item, i) => (
            <li key={i} className="h-full">
              <DesktopItem item={item} />
            </li>
          ))}
        </ul>
        {actions && <div className="flex shrink-0 items-center gap-2">{actions}</div>}
      </nav>
    </header>
  )
}

"use client"

import * as React from "react"
import { Drawer as DrawerPrimitive } from "@base-ui/react/drawer"

import { cn } from "@/lib/utils"

type DrawerContextProps = {
  hasSnapPoints: boolean
  modal: DrawerPrimitive.Root.Props["modal"]
  showSwipeHandle: boolean
  swipeDirection: NonNullable<DrawerPrimitive.Root.Props["swipeDirection"]>
}

const DrawerContext = React.createContext<DrawerContextProps | null>(null)

function useDrawer() {
  const context = React.useContext(DrawerContext)

  if (!context) {
    throw new Error("useDrawer must be used within a Drawer.")
  }

  return context
}

function Drawer({
  modal = true,
  showSwipeHandle = false,
  snapPoints,
  swipeDirection = "down",
  ...props
}: DrawerPrimitive.Root.Props & {
  showSwipeHandle?: boolean
}) {
  const hasSnapPoints = snapPoints != null && snapPoints.length > 0
  const contextValue = React.useMemo(
    () => ({ hasSnapPoints, modal, showSwipeHandle, swipeDirection }),
    [hasSnapPoints, modal, showSwipeHandle, swipeDirection]
  )

  return (
    <DrawerContext.Provider value={contextValue}>
      <DrawerPrimitive.Root
        data-slot="drawer"
        modal={modal}
        snapPoints={snapPoints}
        swipeDirection={swipeDirection}
        {...props}
      />
    </DrawerContext.Provider>
  )
}

function DrawerTrigger({ ...props }: DrawerPrimitive.Trigger.Props) {
  return <DrawerPrimitive.Trigger data-slot="drawer-trigger" {...props} />
}

function DrawerPortal({ ...props }: DrawerPrimitive.Portal.Props) {
  return <DrawerPrimitive.Portal data-slot="drawer-portal" {...props} />
}

function DrawerClose({ ...props }: DrawerPrimitive.Close.Props) {
  return <DrawerPrimitive.Close data-slot="drawer-close" {...props} />
}

function DrawerOverlay({
  className,
  ...props
}: DrawerPrimitive.Backdrop.Props) {
  return (
    <DrawerPrimitive.Backdrop
      data-slot="drawer-overlay"
      className={cn(
        // Rendered INSIDE the fixed Viewport and anchored to it with
        // absolute inset-0: on iOS Safari a document-anchored fixed/absolute
        // backdrop drifts against the visual viewport (toolbar collapse,
        // deep scroll positions) — the viewport is the only element that
        // reliably tracks the visible area, so the backdrop borrows its box.
        // No backdrop-filter either: blurred layers lag the visual viewport.
        "absolute inset-0 z-0 bg-black/20 opacity-[max(var(--drawer-overlay-min-opacity,0),calc(1-var(--drawer-swipe-progress)))] transition-opacity duration-450 ease-[cubic-bezier(0.32,0.72,0,1)] select-none data-ending-style:pointer-events-none data-ending-style:opacity-0 data-ending-style:duration-[calc(var(--drawer-swipe-strength)*400ms)] data-snap-points:[--drawer-overlay-min-opacity:0.5] data-starting-style:opacity-0 data-swiping:duration-0",
        className
      )}
      {...props}
    />
  )
}

function DrawerSwipeHandle({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-swipe-handle"
      aria-hidden="true"
      className={cn(
        "relative z-10 flex shrink-0 cursor-grab transition-opacity duration-200 group-data-nested-drawer-open/drawer-popup:opacity-0 group-data-nested-drawer-swiping/drawer-popup:opacity-100 group-data-[swipe-axis=x]/drawer-popup:h-full group-data-[swipe-axis=x]/drawer-popup:w-3 group-data-[swipe-axis=x]/drawer-popup:items-center group-data-[swipe-axis=y]/drawer-popup:h-3 group-data-[swipe-axis=y]/drawer-popup:w-full group-data-[swipe-axis=y]/drawer-popup:justify-center group-data-[swipe-direction=down]/drawer-popup:items-end group-data-[swipe-direction=left]/drawer-popup:order-last group-data-[swipe-direction=left]/drawer-popup:justify-start group-data-[swipe-direction=right]/drawer-popup:justify-end group-data-[swipe-direction=up]/drawer-popup:order-last group-data-[swipe-direction=up]/drawer-popup:items-start after:block after:shrink-0 after:rounded-full after:bg-muted group-data-[swipe-axis=x]/drawer-popup:after:h-24 group-data-[swipe-axis=x]/drawer-popup:after:w-1 group-data-[swipe-axis=y]/drawer-popup:after:h-1 group-data-[swipe-axis=y]/drawer-popup:after:w-24 active:cursor-grabbing",
        className
      )}
      {...props}
    />
  )
}

function DrawerContent({
  className,
  children,
  ...props
}: DrawerPrimitive.Popup.Props) {
  const { hasSnapPoints, modal, showSwipeHandle, swipeDirection } = useDrawer()
  const swipeAxis =
    swipeDirection === "down" || swipeDirection === "up" ? "y" : "x"

  return (
    <DrawerPortal data-slot="drawer-portal">
      <DrawerPrimitive.Viewport
        data-slot="drawer-viewport"
        data-modal={modal}
        data-swipe-direction={swipeDirection}
        className={cn(
          // The viewport is the only fixed element (matching the Base UI demo):
          // the popup is flex-aligned inside it, so it stays glued to the
          // visual edge when iOS Safari's toolbar collapses the viewport.
          "pointer-events-none fixed inset-0 z-50 flex select-none data-[modal=true]:pointer-events-auto",
          "data-[swipe-direction=down]:items-end data-[swipe-direction=down]:justify-center",
          "data-[swipe-direction=up]:items-start data-[swipe-direction=up]:justify-center",
          // side drawers are physical: swipeDirection="right" must sit on the
          // right edge in RTL too, so the logical justify is flipped there.
          "data-[swipe-direction=left]:items-stretch data-[swipe-direction=left]:justify-start data-[swipe-direction=left]:rtl:justify-end",
          "data-[swipe-direction=right]:items-stretch data-[swipe-direction=right]:justify-end data-[swipe-direction=right]:rtl:justify-start"
        )}
      >
        {modal === true && (
          <DrawerOverlay data-snap-points={hasSnapPoints ? "" : undefined} />
        )}
        <DrawerPrimitive.Popup
          data-slot="drawer-popup"
          data-swipe-axis={swipeAxis}
          data-snap-points={hasSnapPoints ? "" : undefined}
          className={cn(

            "group/drawer-popup pointer-events-auto z-50 m-(--drawer-inset,0px) flex h-(--drawer-content-height) max-h-(--drawer-content-max-height,none) min-h-0 w-(--drawer-content-width,auto) transform-[translate3d(var(--translate-x,0px),var(--translate-y,0px),0)_scale(var(--stack-scale))] flex-col border-border bg-popover text-sm text-popover-foreground transition-[transform,height,opacity,filter] duration-450 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform outline-none select-none [interpolate-size:allow-keywords] data-[swipe-direction=down]:rounded-t-xl data-[swipe-direction=down]:border-t data-[swipe-direction=left]:border-r data-[swipe-direction=right]:border-l data-[swipe-direction=up]:rounded-b-xl data-[swipe-direction=up]:border-b",

            "data-nested-drawer-open:overflow-hidden data-nested-drawer-open:brightness-95",

            "after:pointer-events-none after:absolute after:bg-(--drawer-bleed-background,var(--color-popover)) data-[swipe-axis=x]:after:inset-y-0 data-[swipe-axis=x]:after:w-(--bleed) data-[swipe-axis=y]:after:inset-x-0 data-[swipe-axis=y]:after:h-(--bleed) data-[swipe-direction=down]:after:top-full data-[swipe-direction=left]:after:end-full data-[swipe-direction=right]:after:start-full data-[swipe-direction=up]:after:bottom-full",

            "[--drawer-content-height:var(--drawer-height,auto)] data-[swipe-axis=x]:[--drawer-content-width:75%] data-[swipe-axis=y]:[--drawer-content-max-height:calc(100dvh-6rem)] data-[swipe-axis=y]:data-snap-points:[--drawer-content-height:100dvh] data-[swipe-axis=x]:sm:[--drawer-content-width:24rem]",

            "[--bleed:3rem] supports-[-webkit-touch-callout:none]:[--bleed:0px] [--peek:1rem] [--stack-height:var(--drawer-frontmost-height,var(--drawer-height,0px))] [--stack-peek-offset:max(0px,calc((var(--nested-drawers)-var(--stack-progress))*var(--peek)))] [--stack-progress:clamp(0,var(--drawer-swipe-progress),1)] [--stack-scale-base:max(0,calc(1-(var(--nested-drawers)*var(--stack-step))))] [--stack-scale:clamp(0,calc(var(--stack-scale-base)+(var(--stack-step)*var(--stack-progress))),1)] [--stack-shrink:calc(1-var(--stack-scale))] [--stack-step:0.05]",

            "data-ending-style:transform-(--closed-transform) data-ending-style:opacity-[0.9999] data-ending-style:duration-[calc(var(--drawer-swipe-strength)*400ms)] data-nested-drawer-swiping:duration-0 data-ending-style:data-nested-drawer-swiping:duration-[calc(var(--drawer-swipe-strength)*400ms)] data-starting-style:transform-(--closed-transform) data-swiping:duration-0 data-ending-style:data-swiping:duration-[calc(var(--drawer-swipe-strength)*400ms)]",

            "data-[swipe-axis=y]:w-full data-[swipe-axis=y]:data-nested-drawer-open:h-(--stack-height)",

            "data-[swipe-axis=x]:flex-row",

            // iOS home-indicator clearance on the touched edge
            "data-[swipe-direction=down]:pb-[env(safe-area-inset-bottom,0px)] data-[swipe-direction=up]:pt-[env(safe-area-inset-top,0px)]",

            "data-[swipe-direction=down]:origin-bottom data-[swipe-direction=down]:[--closed-transform:translate3d(0,calc(100%+var(--drawer-inset,0px)+2px),0)] data-[swipe-direction=down]:[--translate-y:calc(var(--drawer-snap-point-offset,0px)+var(--drawer-swipe-movement-y)-var(--stack-peek-offset)-(var(--stack-shrink)*var(--stack-height)))]",

            "data-[swipe-direction=up]:origin-top data-[swipe-direction=up]:[--closed-transform:translate3d(0,calc(-100%-var(--drawer-inset,0px)-2px),0)] data-[swipe-direction=up]:[--translate-y:calc(var(--drawer-snap-point-offset,0px)+var(--drawer-swipe-movement-y)+var(--stack-peek-offset)+(var(--stack-shrink)*var(--stack-height)))]",

            "data-[swipe-direction=left]:origin-start data-[swipe-direction=left]:[--closed-transform:translate3d(calc(-100%-var(--drawer-inset,0px)-2px),0,0)] data-[swipe-direction=left]:[--translate-x:calc(var(--drawer-swipe-movement-x)+var(--stack-peek-offset)+(var(--stack-shrink)*100%))]",

            "data-[swipe-direction=right]:origin-end data-[swipe-direction=right]:[--closed-transform:translate3d(calc(100%+var(--drawer-inset,0px)+2px),0,0)] data-[swipe-direction=right]:[--translate-x:calc(var(--drawer-swipe-movement-x)-var(--stack-peek-offset)-(var(--stack-shrink)*100%))]",
            className
          )}
          {...props}
        >
          {showSwipeHandle && <DrawerSwipeHandle />}
          <DrawerPrimitive.Content
            data-slot="drawer-content"
            className={cn(
              "flex min-h-0 flex-1 flex-col overflow-hidden overscroll-contain rounded-[inherit] transition-opacity duration-300 ease-[cubic-bezier(0.45,1.005,0,1.005)] select-text group-data-nested-drawer-open/drawer-popup:opacity-0 group-data-nested-drawer-swiping/drawer-popup:opacity-100 group-data-swiping/drawer-popup:select-none"
            )}
          >
            {children}
          </DrawerPrimitive.Content>
        </DrawerPrimitive.Popup>
      </DrawerPrimitive.Viewport>
    </DrawerPortal>
  )
}

function DrawerHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-header"
      className={cn(
        "flex shrink-0 flex-col gap-0.5 p-4 pb-0 group-data-[swipe-axis=y]/drawer-popup:text-center md:gap-0.5 md:text-start",
        className
      )}
      {...props}
    />
  )
}

function DrawerFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-footer"
      className={cn("mt-auto flex shrink-0 flex-col gap-2 p-4 pt-0", className)}
      {...props}
    />
  )
}

function DrawerTitle({ className, ...props }: DrawerPrimitive.Title.Props) {
  return (
    <DrawerPrimitive.Title
      data-slot="drawer-title"
      className={cn(
        "text-base font-medium text-foreground",
        className
      )}
      {...props}
    />
  )
}

function DrawerDescription({
  className,
  ...props
}: DrawerPrimitive.Description.Props) {
  return (
    <DrawerPrimitive.Description
      data-slot="drawer-description"
      className={cn("text-sm text-balance text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Drawer,
  DrawerPortal,
  DrawerOverlay,
  DrawerSwipeHandle,
  DrawerTrigger,
  DrawerClose,
  DrawerContent,
  DrawerHeader,
  DrawerFooter,
  DrawerTitle,
  DrawerDescription,
}
